#include <vector>
#include <omp.h>

void prefixSum(std::vector<double> const& x, std::vector<double> &output) {
    const std::size_t n = x.size();
    output.resize(n);
    if (n == 0) {
        return;
    }

    const int max_threads = omp_get_max_threads();
    std::vector<double> block_sums(static_cast<std::size_t>(max_threads), 0.0);
    std::vector<double> block_offsets(static_cast<std::size_t>(max_threads), 0.0);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int nthreads = omp_get_num_threads();

        const std::size_t begin =
            (n * static_cast<std::size_t>(tid)) / static_cast<std::size_t>(nthreads);
        const std::size_t end =
            (n * static_cast<std::size_t>(tid + 1)) / static_cast<std::size_t>(nthreads);

        double local_sum = 0.0;
        for (std::size_t i = begin; i < end; ++i) {
            local_sum += x[i];
            output[i] = local_sum; // each thread writes only its own chunk
        }

        block_sums[static_cast<std::size_t>(tid)] = local_sum; // unique per thread

        #pragma omp barrier

        #pragma omp single
        {
            double running = 0.0;
            for (int t = 0; t < nthreads; ++t) {
                block_offsets[static_cast<std::size_t>(t)] = running;
                running += block_sums[static_cast<std::size_t>(t)];
            }
        } // implicit barrier here

        const double offset = block_offsets[static_cast<std::size_t>(tid)];
        for (std::size_t i = begin; i < end; ++i) {
            output[i] += offset; // each thread updates only its own chunk
        }
    }
}
